package com.fitnutri.backend.records;

import com.fitnutri.backend.activity.*;
import com.fitnutri.backend.common.BusinessException;
import com.fitnutri.backend.foodreference.*;
import com.fitnutri.backend.profile.*;
import com.fitnutri.backend.support.PostgresIntegrationSupport;
import com.fitnutri.backend.user.*;
import java.math.BigDecimal;
import java.time.*;
import java.util.*;
import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import static org.junit.jupiter.api.Assertions.*;
class RecordReadIntegrationTest extends PostgresIntegrationSupport {
    @Autowired RecordReadService reads;@Autowired FoodRecordRepository foods;@Autowired ExerciseRecordRepository exercises;@Autowired UserRepository users;@Autowired FoodReferenceRepository references;@Autowired FoodDatasetRepository datasets;@Autowired ExerciseTypeRepository types;@Autowired ActivityDatasetRepository activityDatasets;@Autowired WeightEntryRepository weights;
    private User owner(){var u=new User();u.setEmail("read-record-"+UUID.randomUUID()+"@example.test");u.setDisplayName("Synthetic read fixture");u.setPasswordHash("not-a-login-credential");return users.saveAndFlush(u);}
    private LocalDate day(int d){return LocalDate.of(2020,1,d);}
    private FoodRecord food(User owner,int day,MealType meal){var r=new FoodRecord();r.setUser(owner);r.setFoodName("Synthetic historical food");r.setRecordDate(day(day));r.setRecordedAt(Instant.parse("2026-10-16T10:00:00Z"));r.setClientEntryId(UUID.randomUUID());r.setSource(RecordSource.MANUAL);r.setQuantityGramsSnapshot(new BigDecimal("100.000"));r.setMealType(meal);return foods.saveAndFlush(r);}
    private ExerciseRecord exercise(User owner,int day,ExerciseType type,EstimateStatus status){var r=new ExerciseRecord();r.setUser(owner);r.setExerciseType("Original synthetic activity name");r.setReference(type);r.setRecordDate(day(day));r.setRecordedAt(Instant.parse("2026-10-16T10:00:00Z"));r.setClientEntryId(UUID.randomUUID());r.setSource(RecordSource.MANUAL);r.setDurationMinutes(new BigDecimal("10.50"));r.setEstimateStatus(status);if(type!=null)r.setDataQuality(DataQuality.CURRENT);return exercises.saveAndFlush(r);}
    private ExerciseType type(){var d=new ActivityDataset();d.setName("SYNTHETIC_READ_TEST_ONLY");d.setRelease("test");d.setRevision(UUID.randomUUID().toString());d.setVerified(true);d.setSourceUrl("https://example.test/synthetic");d.setContentSha256("b".repeat(64));d.setMinAge(19);d.setMaxAge(59);activityDatasets.saveAndFlush(d);var t=ExerciseEstimateServiceTest.type();t.setId(null);t.setDataset(d);t.setActivityKey("synthetic-read-"+UUID.randomUUID());return types.saveAndFlush(t);}
    @Test void threeBusinessDatesIgnoreCreationTimestampAndRemainSameAcrossZones(){var u=owner();var a=food(u,1,MealType.LUNCH);food(u,2,MealType.DINNER);food(u,3,MealType.LUNCH);var sydney=reads.listFoods(u.getId(),day(1),day(1),null,"Australia/Sydney");assertEquals(List.of(a.getId().toString()),sydney.stream().map(FoodRecordResponse::id).toList());assertEquals(sydney,reads.listFoods(u.getId(),day(1),day(1),null,"UTC"));assertEquals(2,reads.listFoods(u.getId(),day(1),day(3),MealType.LUNCH,null).size());assertEquals(3,reads.listFoods(u.getId(),day(1),day(3),null,null).size());}
    @Test void foreignAndDeletedIdentitiesAre404AndExcludedFromBothLists(){var u=owner();var other=owner();var ownFood=food(u,1,MealType.LUNCH);var ownExercise=exercise(u,1,null,EstimateStatus.LEGACY_UNVERIFIED);food(other,1,MealType.LUNCH);exercise(other,1,null,EstimateStatus.LEGACY_UNVERIFIED);assertEquals("NOT_FOUND",assertThrows(BusinessException.class,()->reads.getFood(other.getId(),ownFood.getId())).code());assertEquals("NOT_FOUND",assertThrows(BusinessException.class,()->reads.getExercise(other.getId(),ownExercise.getId())).code());assertEquals(1,reads.listFoods(u.getId(),day(1),day(1),null,null).size());ownFood.setDeletedAt(Instant.now());foods.saveAndFlush(ownFood);ownExercise.setDeletedAt(Instant.now());exercises.saveAndFlush(ownExercise);assertTrue(reads.listFoods(u.getId(),day(1),day(1),null,null).isEmpty());assertTrue(reads.listExercises(u.getId(),day(1),day(1),null,null).isEmpty());assertThrows(BusinessException.class,()->reads.getFood(u.getId(),ownFood.getId()));assertThrows(BusinessException.class,()->reads.getExercise(u.getId(),ownExercise.getId()));}
    @Test void legacyFoodNullAndZeroUsePersistedSnapshotsAndPhotoNormalizationNeverWrites(){var u=owner();var f=food(u,1,MealType.SNACK);f.setSource(RecordSource.PHOTO);f.setCalories(999.0);f.setEnergyKj(null);f.setProteinGramsSnapshot(new BigDecimal("0.000"));foods.saveAndFlush(f);var dto=reads.getFood(u.getId(),f.getId());assertNull(dto.nutrients().energyKj());assertEquals(new BigDecimal("0.000"),dto.nutrients().proteinGrams());assertEquals("IMAGE",dto.source());assertNull(dto.reference());assertEquals(DataQuality.LEGACY_UNVERIFIED,dto.dataQuality());assertEquals(RecordSource.PHOTO,foods.findById(f.getId()).orElseThrow().getSource());assertEquals(dto,reads.listFoods(u.getId(),day(1),day(1),null,null).getFirst());}
    @Test void nullableLegacyReferenceIsNotDroppedByUnfilteredExerciseQueryAndTypedFilterStaysInDatabase(){var u=owner();var a=type();var b=type();var legacy=exercise(u,1,null,EstimateStatus.LEGACY_UNVERIFIED);var selected=exercise(u,2,a,EstimateStatus.MISSING_WEIGHT);exercise(u,3,b,EstimateStatus.MISSING_WEIGHT);assertEquals(3,reads.listExercises(u.getId(),day(1),day(3),null,null).size());assertEquals(List.of(selected.getId().toString()),reads.listExercises(u.getId(),day(1),day(3),a.getId(),null).stream().map(ExerciseRecordResponse::id).toList());var dto=reads.getExercise(u.getId(),legacy.getId());assertNull(dto.exerciseType());assertEquals("Original synthetic activity name",dto.exerciseName());assertNull(dto.estimatedKj());assertNull(dto.weightDateUsed());}
    @Test void inactiveFoodReferenceAndStoredNutrientsStayHistoricalWithoutActiveLookup(){var u=owner();var d=new FoodDataset();d.setName("SYNTHETIC_READ_TEST_ONLY");d.setRelease("test");d.setRevision(UUID.randomUUID().toString());d.setVerified(true);d.setSourceUrl("https://example.test/synthetic");d.setContentSha256("c".repeat(64));d.setNutrientPolicy("CORE4_REQUIRED");datasets.saveAndFlush(d);var f=new FoodReference();f.setDataset(d);f.setPublicFoodKey("synthetic-read-"+UUID.randomUUID());f.setFoodName("Immutable synthetic name");f.setDisplayName("Immutable synthetic name");f.setEnergyKj100g(new BigDecimal("100"));f.setProteinG100g(BigDecimal.ZERO);f.setFatG100g(BigDecimal.ZERO);f.setCarbsG100g(BigDecimal.ZERO);f.setActive(true);references.saveAndFlush(f);var r=food(u,1,MealType.LUNCH);r.setReference(f);r.setEnergyKj(new BigDecimal("100.000"));foods.saveAndFlush(r);f.setActive(false);references.saveAndFlush(f);var dto=reads.getFood(u.getId(),r.getId());assertFalse(dto.reference().active());assertEquals(f.getId().toString(),dto.reference().referenceId());assertEquals(new BigDecimal("100.000"),dto.nutrients().energyKj());assertEquals(d.getId().toString(),dto.reference().dataset().id());}
    @Test void unavailableAndAvailableExerciseSnapshotsDoNotRecomputeFromLaterWeights(){var u=owner();var t=type();var unavailable=exercise(u,1,t,EstimateStatus.MISSING_WEIGHT);var available=exercise(u,2,null,EstimateStatus.LEGACY_UNVERIFIED);available.setReference(t);available.setDataQuality(DataQuality.CURRENT);available.setEstimateStatus(EstimateStatus.AVAILABLE);available.setWeightKgUsed(new BigDecimal("70"));available.setWeightDateUsed(day(1));available.setMetUsed(new BigDecimal("3.5"));available.setEstimatedKj(new BigDecimal("179.389"));available.setFormulaVersion(ExerciseEstimateService.FORMULA_VERSION);exercises.saveAndFlush(available);weights.saveAndFlush(WeightEntry.of(u,new BigDecimal("80"),day(2)));t.setActive(false);types.saveAndFlush(t);var old=reads.getExercise(u.getId(),available.getId());assertEquals(new BigDecimal("179.389"),old.estimatedKj());assertEquals(new BigDecimal("70.00"),old.weightKgUsed());assertFalse(old.exerciseType().active());var missing=reads.getExercise(u.getId(),unavailable.getId());assertNull(missing.estimatedKj());assertNull(missing.metUsed());assertEquals(EstimateStatus.MISSING_WEIGHT,missing.estimateStatus());}
    @Test void validEmptyDateRangeAndUnknownTypeFilterAreEmptyNotAReadFailure(){var u=owner();food(u,1,MealType.LUNCH);assertTrue(reads.listFoods(u.getId(),day(2),day(3),null,null).isEmpty());assertTrue(reads.listExercises(u.getId(),day(1),day(3),999999999L,null).isEmpty());assertThrows(BusinessException.class,()->reads.listFoods(u.getId(),day(1),day(3),null,"Not/AZone"));}
}
